00045 namespace lctm {
00046 
00047 struct RegisteredSEI {
00048     static void extract_enhancement_sei(const uint8_t *data, size_t size, bool emulation_prevention, uint64_t pts, bool is_base_idr,
00049                                         std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback);
00050 };
00051 
00052 struct UnregisteredSEI {
00053     static void extract_enhancement_sei(const uint8_t *data, size_t size, bool emulation_prevention, uint64_t pts, bool is_base_idr,
00054                                         std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback);
00055 };
00056 
00058 //
00059 class rbsp_decoder {
00060 public:
00061     rbsp_decoder(const uint8_t *d, size_t l, bool e) : data(d), len(l), emulatiom_prevention(e), emitted(0xFFFFFFFF), offs(0){};
00062     uint8_t get_byte();
00063     uint8_t *copy_sei(uint8_t *dst, size_t len);
00064     void copy(PacketBuilder *dst);
00065 
00066 protected:
00067     const uint8_t *data;
00068     size_t len;
00069     bool emulatiom_prevention;
00070     uint32_t emitted;
00071     size_t offs;
00072 };
00073 
00074 uint8_t rbsp_decoder::get_byte() {
00075     if (offs >= len)
00076         throw out_of_range("No more RBSP");
00077 
00078     emitted <<= 8;
00079     emitted |= data[offs++];
00080     if (emulatiom_prevention && (emitted & 0xFFFFFF) == 0x000003) {
00081         emitted <<= 8;
00082         if (offs >= len)
00083             throw out_of_range("No more RBSP");
00084 
00085         emitted |= data[offs++];
00086     }
00087     return emitted & 0xFF;
00088 }
00089 
00090 uint8_t *rbsp_decoder::copy_sei(uint8_t *d, size_t l) {
00091     for (size_t i = 0; i < l; i++)
00092         d[i] = get_byte();
00093 
00094     return d;
00095 }
00096 
00097 void rbsp_decoder::copy(PacketBuilder *dst) {
00098     size_t i = 0;
00099     dst->reserve((uint32_t)len - (uint32_t)offs);
00100     while (true) {
00101         try {
00102             dst->data()[i] = get_byte();
00103         } catch (const std::out_of_range &) {
00104             dst->resize((uint32_t)i -
00105                         1); // 0x80 is added during encapsulation process but does not belong to the actual data - stop bit
00106             return;
00107         }
00108         i++;
00109     }
00110 }
00111 
00112 // Recognize the NALU marker (used by LCEVC,AVC,HEVC,VVC, but not EVC)
00113 //
00114 static inline bool is_nal_marker(const uint8_t *data) { return data[0] == 0 && data[1] == 0 && data[2] == 1; }
00115 
00116 // Check for valid LCEVC NAL uint type
00117 //
00118 static inline bool is_lcevc_nal_unit_type(const uint8_t b) { return (b >= LCEVC_NON_IDR) && (b <= LCEVC_RSV); }
00119 
00120 // Extract enhancement data and pass to callback
00121 //
00122 static void extract_enhancement_nal(const uint8_t *data, size_t size, bool emulation_prevention, uint64_t pts, const bool is_idr,
00123                                     std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00124 
00125     auto pss = Packet::build();
00126     pss.timestamp(pts);
00127 
00128     if (emulation_prevention) {
00129         rbsp_decoder rbsp(data, size, true);
00130         rbsp.copy(&pss);
00131     } else {
00132         pss.contents(data, (unsigned)size);
00133     }
00134     callback(pss.finish(), is_idr);
00135 }
00136 
00137 // Find any enhancement data in native LCEVC NAL Unit and pass to callback
00138 //
00139 static size_t scan_enhancement_nal(uint8_t *data, size_t data_size, uint64_t pts,
00140                                    std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00141     // Scan for Enhancement NALU
00142     for (unsigned i = 0; i < data_size - 4; ++i) {
00143         if (is_nal_marker(data + i) && (data[i + 3] & 0xc0) == 0x40 && data[i + 4] == 0xff) {
00144             const unsigned nal_unit_type = (data[i + 3] & 0x3e) >> 1;
00145 
00146             if (is_lcevc_nal_unit_type(nal_unit_type)) {
00147                 const bool is_idr = (nal_unit_type == NalUnitType::LCEVC_IDR ? true : false);
00148 
00149                 // Figure size of NALU
00150                 unsigned e = (unsigned)data_size;
00151                 for (unsigned j = i + 4; j < data_size - 3; ++j) {
00152                     if (is_nal_marker(data + j)) {
00153                         // Handle [0, 0, 0, 1] case
00154                         if (data[j - 1] == 0x00)
00155                             j--;
00156                         e = j;
00157                         break;
00158                     }
00159                 }
00160                 extract_enhancement_nal(data + (i + 5), e - (i + 5), true, pts, is_idr, callback);
00161 
00162                 // Remove enhancement data from bitstream leaving base codec bitstream
00163                 memmove(data + i, data + e, data_size - e);
00164                 data_size = data_size + i - e;
00165             }
00166         }
00167     }
00168 
00169     return data_size;
00170 }
00171 
00172 // Find any enhancement data in native EVC NAL Unit (u32 length-prefix) and pass to callback
00173 //
00174 static size_t scan_enhancement_nal_evc(uint8_t *data, size_t data_size, uint64_t pts,
00175                                        std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00176     unsigned offset = 0;
00177 
00178     while (offset < data_size - 6) {
00179         uint32_t nal_length = 0;
00180         memcpy(&nal_length, data + offset, 4);
00181         uint32_t total_length = nal_length + 4;
00182 
00183         if ((data[offset + 4] & 0xfe) == 0x3c && (data[offset + 5] & 0x3f) == 0x00) {
00184             const unsigned nal_unit_type = (data[offset + 4] & 0xf8) >> 3;
00185             const bool is_idr = (nal_unit_type == NalUnitType::LCEVC_IDR ? true : false);
00186 
00187             extract_enhancement_nal(data + offset + 6, nal_length - 2, false, pts, is_idr, callback);
00188 
00189             memmove(data + offset, data + offset + total_length, data_size - (offset + total_length));
00190             data_size -= total_length;
00191         } else {
00192             offset += total_length;
00193         }
00194     }
00195 
00196     return data_size;
00197 }
00198 
00199 // Find any enhancement data in native LCEVC NAL Unit and pass to callback (without memmove!)
00200 // Used to extract LCEVC NAL Unit from registered SEI -> required for SDK decoding workflow
00201 //
00202 static void scan_enhancement_nal_prod(const uint8_t *data, size_t data_size, uint64_t pts,
00203                                       std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00204     // Scan for Enhancement NALU
00205     for (unsigned i = 0; i < data_size - 4; ++i) {
00206         if (is_nal_marker(data + i) && (data[i + 3] & 0xc0) == 0x40 && data[i + 4] == 0xff) {
00207             const unsigned nal_unit_type = (data[i + 3] & 0x3e) >> 1;
00208 
00209             if (is_lcevc_nal_unit_type(nal_unit_type)) {
00210                 const bool is_idr = (nal_unit_type == NalUnitType::LCEVC_IDR ? true : false);
00211 
00212                 // Figure size of NALU
00213                 unsigned e = (unsigned)data_size;
00214                 for (unsigned j = i + 4; j < data_size - 3; ++j) {
00215                     if (is_nal_marker(data + j)) {
00216                         // Handle [0, 0, 0, 1] case
00217                         if (data[j - 1] == 0x00)
00218                             j--;
00219                         e = j;
00220                         break;
00221                     }
00222                 }
00223                 extract_enhancement_nal(data + (i + 5), e - (i + 5), true, pts, is_idr, callback);
00224             }
00225         }
00226     }
00227 }
00228 
00229 // Find any enhancement data in registered SEI NALU and pass to callback
00230 // Used as a template parameter to scan_enhancement_sei_XXX()
00231 //
00232 void RegisteredSEI::extract_enhancement_sei(const uint8_t *data, size_t size, bool emulation_prevention, uint64_t pts,
00233                                             bool is_base_idr,
00234                                             std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00235     const unsigned USER_DATA_REGISTERED = 4;
00236     static const uint8_t sei_code[4] = {0xb4, 0x00, 0x50, 0x00};
00237 
00238     rbsp_decoder rbsp(data, size, emulation_prevention);
00239 
00240     size_t sei_type = 0;
00241     uint8_t byte;
00242 
00243     do {
00244         byte = rbsp.get_byte();
00245         sei_type += byte;
00246     } while (byte == 0xFF);
00247 
00248     if (sei_type == USER_DATA_REGISTERED) {
00249         size_t sei_length = 0;
00250         do {
00251             byte = rbsp.get_byte();
00252             sei_length += byte;
00253         } while (byte == 0xFF);
00254 
00255         if (sei_length > size) {
00256             WARN("SEI length overflow");
00257         } else {
00258             uint8_t tmp[sizeof(sei_code)];
00259             rbsp.copy_sei(tmp, sizeof(tmp));
00260 
00261             if (memcmp(sei_code, tmp, sizeof(sei_code)) == 0) {
00262                 int64_t enhancement_len = sei_length - sizeof(sei_code);
00263 
00264                 vector<uint8_t> buf(enhancement_len);
00265                 rbsp.copy_sei(buf.data(), buf.size());
00266 
00267                 // Additional NAL Encapsulation (LCEVC NALU Type)
00268                 scan_enhancement_nal_prod(buf.data(), buf.size(), pts, callback);
00269             }
00270         }
00271     }
00272 }
00273 
00274 // Find any enhancement data in unregistered SEI NALU and pass to callback
00275 // Used as a template parameter to scan_enhancement_sei_XXX()
00276 //
00277 void UnregisteredSEI::extract_enhancement_sei(const uint8_t *data, size_t size, bool emulation_prevention, uint64_t pts,
00278                                               bool is_base_idr,
00279                                               std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00280     const unsigned USER_DATA_UNREGISTERED = 5;
00281     static const uint8_t uuid[16] = {0xa7, 0xc4, 0x6d, 0xed, 0x49, 0xd8, 0x38, 0xeb,
00282                                      0x9a, 0xad, 0x6d, 0xa6, 0x84, 0x97, 0xa7, 0x54};
00283 
00284     rbsp_decoder rbsp(data, size, emulation_prevention);
00285 
00286     size_t sei_type = 0;
00287     uint8_t byte;
00288 
00289     do {
00290         byte = rbsp.get_byte();
00291         sei_type += byte;
00292     } while (byte == 0xFF);
00293 
00294     if (sei_type == USER_DATA_UNREGISTERED) {
00295         size_t sei_length = 0;
00296         do {
00297             byte = rbsp.get_byte();
00298             sei_length += byte;
00299         } while (byte == 0xFF);
00300 
00301         if (sei_length > size) {
00302             WARN("SEI length overflow");
00303         } else {
00304             uint8_t tmp[sizeof(uuid)];
00305             rbsp.copy_sei(tmp, sizeof(tmp));
00306 
00307             if (memcmp(uuid, tmp, sizeof(uuid)) == 0) {
00308                 int64_t enhancement_len = sei_length - sizeof(uuid);
00309 
00310                 auto pss = Packet::build();
00311                 pss.reserve((unsigned)enhancement_len);
00312                 pss.timestamp(pts);
00313                 rbsp.copy_sei(pss.data(), enhancement_len);
00314                 callback(pss.finish(), is_base_idr);
00315             }
00316         }
00317     }
00318 }
00319 
00320 // AVC NALUs headers have one byte for type
00321 template <typename SEI>
00322 static size_t scan_enhancement_sei_avc(uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr,
00323                                        std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00324     // Scan for SEI NALU
00325     for (unsigned i = 0; i < data_size - 4; ++i) {
00326         if (is_nal_marker(data + i) && data[i + 3] == 0x6) {
00327             // Figure size of NALU
00328             unsigned e = (unsigned)data_size;
00329             for (unsigned j = i + 4; j < data_size - 3; ++j) {
00330                 if (is_nal_marker(data + j)) {
00331                     e = j;
00332                     break;
00333                 }
00334             }
00335             SEI::extract_enhancement_sei(data + (i + 4), e - (i + 4), true, pts, is_base_idr, callback);
00336         }
00337     }
00338 
00339     // SEI can survive base decoder - don't remove
00340     return data_size;
00341 }
00342 
00343 // HEVC NALUs headers have two bytes for type
00344 template <typename SEI>
00345 static size_t scan_enhancement_sei_hevc(uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr,
00346                                         std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00347     // Scan for SEI NALU
00348     for (unsigned i = 0; i < data_size - 5; ++i) {
00349         if (is_nal_marker(data + i) && data[i + 3] == 0x4e && data[i + 4] == 0x01) {
00350             // Figure size of NALU
00351             unsigned e = (unsigned)data_size;
00352             for (unsigned j = i + 4; j < data_size - 3; ++j) {
00353                 if (is_nal_marker(data + j)) {
00354                     e = j;
00355                     break;
00356                 }
00357             }
00358             SEI::extract_enhancement_sei(data + (i + 5), e - (i + 5), true, pts, is_base_idr, callback);
00359         }
00360     }
00361 
00362     // SEI can survive base decoder - don't remove
00363     return data_size;
00364 }
00365 
00366 // VVC NALUs headers have two bytes for type
00367 template <typename SEI>
00368 static size_t scan_enhancement_sei_vvc(uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr,
00369                                        std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00370     // Scan for SEI NALU
00371     for (unsigned i = 0; i < data_size - 5; ++i) {
00372         if (is_nal_marker(data + i) && data[i + 3] == 0x00 && (data[i + 4] & 0xf8) == 0xb8) {
00373             // Figure size of NALU
00374             unsigned e = (unsigned)data_size;
00375             for (unsigned j = i + 4; j < data_size - 3; ++j) {
00376                 if (is_nal_marker(data + j)) {
00377                     e = j;
00378                     break;
00379                 }
00380             }
00381             SEI::extract_enhancement_sei(data + (i + 5), e - (i + 5), true, pts, is_base_idr, callback);
00382         }
00383     }
00384 
00385     // SEI can survive base decoder - don't remove
00386     return data_size;
00387 }
00388 
00389 // EVC NALUs are u32 size prefixed, not marker delimited
00390 template <typename SEI>
00391 static size_t scan_enhancement_sei_evc(uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr,
00392                                        std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00393 
00394     unsigned offset = 0;
00395 
00396     while (offset < data_size - 6) {
00397         uint32_t nal_length = 0;
00398         memcpy(&nal_length, data + offset, 4);
00399         uint32_t total_length = nal_length + 4;
00400 
00401         if ((data[offset + 4] & 0xfe) == 0x38 && (data[offset + 5] & 0x3f) == 0x00) {
00402             SEI::extract_enhancement_sei(data + 6, nal_length - 2, false, pts, is_base_idr, callback);
00403         }
00404         offset += total_length;
00405     }
00406 
00407     // SEI can survive base decoder - don't remove
00408     return data_size;
00409 }
00410 
00411 // Scan for enhancement data in buffer - may remove data and returns new size
00412 //
00413 size_t scan_enhancement(uint8_t *data, size_t data_size, Encapsulation encapsulation, BaseCoding base_coding, uint64_t pts,
00414                         bool is_base_idr, std::function<void(const Packet &pkt, const bool is_lcevc_idr)> callback) {
00415     switch (encapsulation) {
00416     case Encapsulation_SEI_Registered:
00417         switch (base_coding) {
00418         case BaseCoding_AVC:
00419             return scan_enhancement_sei_avc<RegisteredSEI>(data, data_size, pts, is_base_idr, callback);
00420         case BaseCoding_HEVC:
00421             return scan_enhancement_sei_hevc<RegisteredSEI>(data, data_size, pts, is_base_idr, callback);
00422         case BaseCoding_VVC:
00423             return scan_enhancement_sei_vvc<RegisteredSEI>(data, data_size, pts, is_base_idr, callback);
00424         case BaseCoding_EVC:
00425             return scan_enhancement_sei_evc<RegisteredSEI>(data, data_size, pts, is_base_idr, callback);
00426         default:
00427             CHECK(0);
00428         }
00429         break;
00430     case Encapsulation_SEI_Unregistered:
00431         switch (base_coding) {
00432         case BaseCoding_AVC:
00433             return scan_enhancement_sei_avc<UnregisteredSEI>(data, data_size, pts, is_base_idr, callback);
00434         case BaseCoding_HEVC:
00435             return scan_enhancement_sei_hevc<UnregisteredSEI>(data, data_size, pts, is_base_idr, callback);
00436         case BaseCoding_VVC:
00437             return scan_enhancement_sei_vvc<UnregisteredSEI>(data, data_size, pts, is_base_idr, callback);
00438         case BaseCoding_EVC:
00439             return scan_enhancement_sei_evc<UnregisteredSEI>(data, data_size, pts, is_base_idr, callback);
00440         default:
00441             CHECK(0);
00442         }
00443         break;
00444     case Encapsulation_NAL:
00445         switch (base_coding) {
00446         case BaseCoding_AVC:
00447             return scan_enhancement_nal(data, data_size, pts, callback);
00448         case BaseCoding_HEVC:
00449             return scan_enhancement_nal(data, data_size, pts, callback);
00450         case BaseCoding_VVC:
00451             return scan_enhancement_nal(data, data_size, pts, callback);
00452         case BaseCoding_EVC:
00453             return scan_enhancement_nal_evc(data, data_size, pts, callback);
00454         case BaseCoding_YUV:
00455             return scan_enhancement_nal(data, data_size, pts, callback);
00456         default:
00457             CHECK(0);
00458         }
00459         break;
00460     case Encapsulation_None:
00461         return scan_enhancement_nal(data, data_size, pts, callback);
00462 
00463     default:
00464         CHECK(0);
00465     }
00466 
00467     return 0;
00468 }
00469 } // namespace lctm
